const weekStart = $now.startOf('week').toISODate();
if (!/^\d{4}-\d{2}-\d{2}$/.test(weekStart)) {
  throw new Error(`Could not resolve week start: ${weekStart}`);
}
const parsed = new Date(`${weekStart}T00:00:00Z`);
if (Number.isNaN(parsed.getTime()) || parsed.getUTCDay() !== 1) {
  throw new Error(`Resolved week start is not a Monday: ${weekStart}`);
}
return [{ json: { week_start: weekStart } }];

if (typeof $json.stdout !== 'string' || $json.stdout.trim() === '') {
  throw new Error('Forecast command returned no JSON');
}
let payload;
try {
  payload = JSON.parse($json.stdout);
} catch (error) {
  throw new Error(`Forecast command returned invalid JSON: ${error.message}`);
}
const monday = /^\d{4}-\d{2}-\d{2}$/;
if (!monday.test(payload.week_start ?? '') || !monday.test(payload.source_week_start ?? '')) {
  throw new Error('Forecast response has invalid week dates');
}
const target = new Date(`${payload.week_start}T00:00:00Z`);
const source = new Date(`${payload.source_week_start}T00:00:00Z`);
if (Number.isNaN(target.getTime()) || Number.isNaN(source.getTime()) || target - source !== 7 * 86400000) {
  throw new Error('Forecast source must be exactly one week before its target');
}
if (payload.predicted !== true || !Array.isArray(payload.languages) || !Array.isArray(payload.releases)) {
  throw new Error('Forecast response is missing prediction metadata or arrays');
}
for (const release of payload.releases) {
  if (!release || typeof release.title !== 'string' || release.title.trim() === '' || typeof release.language !== 'string' || release.language.trim() === '' || typeof release.starts_at !== 'string' || Number.isNaN(Date.parse(release.starts_at)) || typeof release.source_starts_at !== 'string' || Number.isNaN(Date.parse(release.source_starts_at)) || typeof release.url !== 'string' || !release.url.startsWith('https://www.crunchyroll.com/') || release.predicted !== true) {
    throw new Error('Forecast response contains an invalid release');
  }
  if (Date.parse(release.starts_at) - Date.parse(release.source_starts_at) !== 7 * 86400000) {
    throw new Error(`Forecast release is not seven days after its source: ${release.title}`);
  }
}
return [{ json: payload }];

const payload = $json;
return payload.releases.map((release) => ({
  json: {
    week_start: payload.week_start,
    source_week_start: payload.source_week_start,
    ...release
  }
}));
